	minQD := snapshots[0].QueueDepth + snapshots[0].PendingRequests
	minLoad := snapshots[0].EffectiveLoad()
	for _, snap := range snapshots[1:] {
		qd := snap.QueueDepth + snap.PendingRequests
		if qd < minQD {
			minQD = qd
		}
		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
